/** 初始化所有PRG Bank到PrgLoader */
export function loadAllPrgBanks(loadFn: (bankId: number, data: Uint8Array) => void): void {
  for (const [bankIdStr, base64] of Object.entries(PRG_BANK_BASE64)) {
    const bankId = parseInt(bankIdStr, 10);
    const binary = atob(base64);
    const data = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      data[i] = binary.charCodeAt(i);
    }
    loadFn(bankId, data);
  }
}